import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 계획 연월은 YYYY-MM 형식이다.
const MONTH_PATTERN = /^\d{4}-(0[1-9]|1[0-2])$/;
const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;
// 가정: 등록 시 계획 상태 초기값은 기안이다.
const INITIAL_STATUS = '기안';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function idOf(value: unknown, label: string): string {
  const text = typeof value === 'number' || typeof value === 'string' ? String(value).trim() : '';
  if (!/^\d+$/.test(text)) {
    throw invalid(label + '을(를) 올바르게 입력해 주세요.');
  }
  return text;
}

function monthOf(value: unknown): string {
  const text = typeof value === 'string' ? value.trim() : '';
  if (!MONTH_PATTERN.test(text)) {
    throw invalid('계획 연월은 YYYY-MM 형식으로 입력해 주세요.');
  }
  return text;
}

function dateOf(value: unknown): string {
  const text = typeof value === 'string' ? value.trim() : '';
  const match = DATE_PATTERN.exec(text);
  if (!match) {
    throw invalid('계획 일자는 YYYY-MM-DD 형식으로 입력해 주세요.');
  }
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const lastDays = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (month < 1 || month > 12 || day < 1 || day > lastDays[month - 1]) {
    throw invalid('계획 일자가 올바른 날짜가 아닙니다.');
  }
  return text;
}

function optionalText(value: unknown): string | null {
  if (value === undefined || value === null) {
    return null;
  }
  const text = String(value).trim();
  return text === '' ? null : text;
}

@Controller('api/v1')
export class FnSfr01706Controller {
  @Get('/annual-leave-plans')
  async listAnnualLeavePlans(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const query = checks.queryOf(req.query);
    const planMonthText = optionalText(query['planMonth']);
    const planMonth = planMonthText === null ? null : monthOf(planMonthText);
    const employeeText = optionalText(query['employeeId']);
    const employeeId = employeeText === null ? null : idOf(employeeText, '임직원');
    const pageText = optionalText(query['page']);
    const sizeText = optionalText(query['size']);
    if ((pageText !== null && !/^\d+$/.test(pageText)) || (sizeText !== null && !/^\d+$/.test(sizeText))) {
      throw invalid('page와 size는 숫자로 입력해 주세요.');
    }
    const page = pageText === null ? 0 : Number(pageText);
    const size = Math.min(sizeText === null ? DEFAULT_SIZE : Math.max(Number(sizeText), 1), MAX_SIZE);
    return transaction(async (db) => {
      const where =
        'WHERE (CAST(:planMonth AS varchar) IS NULL OR plan_month = CAST(:planMonth AS varchar))' +
        ' AND (CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint))';
      const items = await db.query(
        'SELECT annual_leave_plan_id AS "annualLeavePlanId",' +
          ' employee_id AS "employeeId",' +
          ' plan_month AS "planMonth",' +
          " to_char(plan_date, 'YYYY-MM-DD') AS \"planDate\"," +
          ' plan_status AS "planStatus"' +
          ' FROM annual_leave_plan ' +
          where +
          ' ORDER BY plan_date DESC, annual_leave_plan_id DESC' +
          ' LIMIT :size OFFSET :offset',
        { planMonth, employeeId, size, offset: page * size },
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM annual_leave_plan ' + where,
        { planMonth, employeeId },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/annual-leave-plans')
  @HttpCode(200)
  async createAnnualLeavePlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body);
    const employeeId = idOf(data['employeeId'], '임직원');
    const planMonth = monthOf(data['planMonth']);
    const planDate = dateOf(data['planDate']);
    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '대상 임직원을 찾을 수 없습니다.');
      }
      const duplicates = await db.query(
        'SELECT annual_leave_plan_id FROM annual_leave_plan' +
          ' WHERE employee_id = CAST(:employeeId AS bigint) AND plan_date = CAST(:planDate AS date)',
        { employeeId, planDate },
      );
      if (duplicates.length > 0) {
        throw new ApiError(409, 'ANNUAL_LEAVE_PLAN_DUPLICATED', '같은 임직원의 같은 일자 연차계획이 이미 있습니다.');
      }
      const rows = await db.query(
        'INSERT INTO annual_leave_plan' +
          ' (employee_id, plan_month, plan_date, plan_status, created_at, updated_at)' +
          ' VALUES (CAST(:employeeId AS bigint), :planMonth, CAST(:planDate AS date), :planStatus, now(), now())' +
          ' RETURNING annual_leave_plan_id AS "annualLeavePlanId"',
        { employeeId, planMonth, planDate, planStatus: INITIAL_STATUS },
      );
      return { annualLeavePlanId: Number(rows[0]['annualLeavePlanId']) };
    });
  }

  @Put('/annual-leave-plans/:annualLeavePlanId')
  async updateAnnualLeavePlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const annualLeavePlanId = idOf(req.params['annualLeavePlanId'], '연차계획');
    const data = checks.inputOf(req.body);
    const planMonth = monthOf(data['planMonth']);
    const planDate = dateOf(data['planDate']);
    return transaction(async (db) => {
      const plans = await db.query(
        'SELECT employee_id AS "employeeId" FROM annual_leave_plan' +
          ' WHERE annual_leave_plan_id = CAST(:annualLeavePlanId AS bigint)',
        { annualLeavePlanId },
      );
      if (plans.length === 0) {
        throw new ApiError(404, 'ANNUAL_LEAVE_PLAN_NOT_FOUND', '연차계획을 찾을 수 없습니다.');
      }
      const duplicates = await db.query(
        'SELECT annual_leave_plan_id FROM annual_leave_plan' +
          ' WHERE employee_id = CAST(:employeeId AS bigint)' +
          ' AND plan_date = CAST(:planDate AS date)' +
          ' AND annual_leave_plan_id <> CAST(:annualLeavePlanId AS bigint)',
        { employeeId: String(plans[0]['employeeId']), planDate, annualLeavePlanId },
      );
      if (duplicates.length > 0) {
        throw new ApiError(409, 'ANNUAL_LEAVE_PLAN_DUPLICATED', '같은 임직원의 같은 일자 연차계획이 이미 있습니다.');
      }
      await db.execute(
        'UPDATE annual_leave_plan SET plan_month = :planMonth,' +
          ' plan_date = CAST(:planDate AS date), updated_at = now()' +
          ' WHERE annual_leave_plan_id = CAST(:annualLeavePlanId AS bigint)',
        { planMonth, planDate, annualLeavePlanId },
      );
      return { annualLeavePlanId: Number(annualLeavePlanId) };
    });
  }
}

