import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Tiles,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  DateInput,
  LookupSelect,
  RefName,
  ErrorText,
  DateText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const PAGE_SIZE = 20;
const MONTH_PATTERN = /^\d{4}-(0[1-9]|1[0-2])$/;

export default function FnSfr01706Page({ role, notify }: PageProps) {
  const [planMonth, setPlanMonth] = useState('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState<Row | null>(null);

  const [newEmployeeId, setNewEmployeeId] = useState<number | string>('');
  const [newMonth, setNewMonth] = useState('');
  const [newDate, setNewDate] = useState('');
  const [editMonth, setEditMonth] = useState('');
  const [editDate, setEditDate] = useState('');

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/annual-leave-plans', role, undefined, { ...applied, page, size: PAGE_SIZE }),
    [applied, page],
  );

  const search = () => {
    setPage(0);
    setApplied({ planMonth, employeeId });
  };

  const reset = () => {
    setPlanMonth('');
    setEmployeeId('');
    setPage(0);
    setApplied({});
  };

  const openCreate = () => {
    setNewEmployeeId('');
    setNewMonth('');
    setNewDate('');
    setCreating(true);
  };

  const openEdit = (row: Row) => {
    setEditMonth(String(row['planMonth'] ?? ''));
    setEditDate(String(row['planDate'] ?? ''));
    setEditing(row);
  };

  const create = async () => {
    if (newEmployeeId === '' || !newMonth || !newDate) {
      throw new Error('임직원, 계획 연월, 계획 일자를 모두 입력해 주세요.');
    }
    if (!MONTH_PATTERN.test(newMonth)) {
      throw new Error('계획 연월은 YYYY-MM 형식으로 입력해 주세요.');
    }
    await call('POST', '/annual-leave-plans', role, {
      employeeId: newEmployeeId,
      planMonth: newMonth,
      planDate: newDate,
    });
    notify('연차계획을 등록했습니다.');
    setCreating(false);
    reload();
  };

  const update = async () => {
    if (!editing) {
      return;
    }
    if (!editMonth || !editDate) {
      throw new Error('계획 연월과 계획 일자를 모두 입력해 주세요.');
    }
    if (!MONTH_PATTERN.test(editMonth)) {
      throw new Error('계획 연월은 YYYY-MM 형식으로 입력해 주세요.');
    }
    await call('PUT', '/annual-leave-plans/' + String(editing['annualLeavePlanId']), role, {
      planMonth: editMonth,
      planDate: editDate,
    });
    notify('연차계획을 수정했습니다.');
    setEditing(null);
    reload();
  };

  const rows = data ? data.items : [];
  const total = data ? data.total : 0;

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>연차계획 현황</h2>
        <Tiles items={[['조회된 계획', total], ['현재 쪽 건수', rows.length]]} />
      </section>
      <section className='box span-12'>
        <h2>월별 연차계획</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='계획 연월'>
            <TextInput value={planMonth} onChange={setPlanMonth} placeholder='YYYY-MM' />
          </Field>
          <Field label='임직원'>
            <LookupSelect table='employee' role={role} value={employeeId} onChange={setEmployeeId} />
          </Field>
        </Filters>
        <Band total={total}>
          <button type='button' onClick={openCreate}>연차계획 등록</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          rows={rows}
          empty='등록된 연차계획이 없습니다.'
          columns={[
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table='employee' role={role} value={r['employeeId']} /> },
            { key: 'planMonth', label: '계획 연월' },
            { key: 'planDate', label: '계획 일자', render: (r) => <DateText value={r['planDate']} /> },
            { key: 'planStatus', label: '계획 상태', render: (r) => <Badge value={r['planStatus']} /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) => <button type='button' onClick={() => openEdit(r)}>수정</button>,
            },
          ]}
        />
        <Pager page={page} size={PAGE_SIZE} total={total} onPage={setPage} />
      </section>
      {creating ? (
        <Drawer title='연차계획 등록' onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit='등록'>
            <Field label='임직원' required>
              <LookupSelect table='employee' role={role} value={newEmployeeId} onChange={setNewEmployeeId} />
            </Field>
            <Field label='계획 연월' required hint='YYYY-MM'>
              <TextInput value={newMonth} onChange={setNewMonth} placeholder='YYYY-MM' />
            </Field>
            <Field label='계획 일자' required>
              <DateInput value={newDate} onChange={setNewDate} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {editing ? (
        <Drawer title='연차계획 수정' onClose={() => setEditing(null)}>
          <Form onSubmit={update} submit='수정'>
            <Field label='임직원'>
              <RefName table='employee' role={role} value={editing['employeeId']} />
            </Field>
            <Field label='계획 연월' required hint='YYYY-MM'>
              <TextInput value={editMonth} onChange={setEditMonth} placeholder='YYYY-MM' />
            </Field>
            <Field label='계획 일자' required>
              <DateInput value={editDate} onChange={setEditDate} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
